// Runtime QA harness for the Design Hub. Serves the Hub statically and runs
// the profile viewports (runtime_qa.viewports). Generated by init-project.sh; edit freely.
import { defineConfig, devices } from '@playwright/test';

// Verification viewports from the profile. Layout modes: compact <600, medium 600-1023, expanded >=1024.
const VIEWPORTS = [1440, 1024, 768, 390];
const mode = (w) => (w < 600 ? 'compact' : w < 1024 ? 'medium' : 'expanded');

const PORT = process.env.HUB_QA_PORT || '4321';
const BASE_URL = `http://localhost:${PORT}`;

export default defineConfig({
  testDir: './tests',
  timeout: 30000,
  fullyParallel: false,
  reporter: [['list'], ['html', { open: 'never' }]],
  webServer: {
    command: `python3 -m http.server ${PORT} --directory ..`,
    url: BASE_URL,
    reuseExistingServer: true,
    timeout: 20000,
  },
  use: { baseURL: BASE_URL, screenshot: 'only-on-failure', trace: 'retain-on-failure' },
  projects: VIEWPORTS.map((w) => ({
    name: `${mode(w)}-${w}`,
    use: {
      ...devices['Desktop Chrome'],
      viewport: { width: w, height: w < 600 ? 780 : 900 },
      ...(w < 600 ? { hasTouch: true, isMobile: true } : {}),
    },
  })),
});
